mapper.select:
select zw.bm as code,zw.hzmc as name ,sum(case when uszw.rybm is not null then 1 else 0 end) as count from Zzzd_Zwmc zw left join ( select b.rybm,b.ZWMC from zz_bzcyxx b inner join zz_zzqkxxfb fb on b.DZZDM = fb.DZZDM and b.jc = fb.LDJTJC inner join zz_zzqkxx p on fb.DZZDM = p.DZZDM inner join vm_ryjbxx us on b.rybm = us.RYBM where (b.PZMZRQ is null or b.PZMZRQ='')
and us.SZDZBDM like concat('',#{dzzdm},'%')
) uszw on zw.bm = uszw.ZWMC group by zw.bm,zw.hzmc order by zw.xh

select t1.DZZTYPE ,(case t1.DZZTYPE when 1 then '党委' when 2 then '党工委' when 3 then '党总支' when 4 then '党支部' when 5 then '其他' else '' end) TYPENAME ,ifnull(t2.num,0) NUM from (select dic.DICKEY as DZZTYPE from cf_dictionary dic where dic.DICTYPEKEY='monthType' and dic.DICKEY <= 5) t1 left join (select DZZTYPE,count(*) num from (select (case when ZZLB in ('611') and length(DZZDM)=12 then 1 -- 党委 when ZZLB in ('200','271') then 2 -- 党工委 when ZZLB in ('621') then 3 -- 党总支 when ZZLB in ('631','633') then 4 -- 党支部 else 5 end ) DZZTYPE, DZZMC, DZZDM from zz_zzqkxx p where 1=1
and p.DZZDM like concat('',#{dzzdm},'%')
) tt1 group by DZZTYPE ) t2 on t1.DZZTYPE=t2.DZZTYPE order by t1.DZZTYPE

select t1.ZZLB ,(case t1.ZZLB when 1 then '党委' when 2 then '党总支' when 3 then '党支部' when 4 then '党小组' else '其他' end) ZZLBMC ,ifnull(t2.num,0) NUM from (select dic.DICKEY as ZZLB from cf_dictionary dic where dic.DICTYPEKEY='monthType' and dic.DICKEY <= 5) t1 left join (select zzlb,count(*) num from ( select distinct z.DZZDM,z.DZZMC, (case when zzlb.HZMC in('党委','党工委') then 1 when zzlb.HZMC in('党总支') then 2 when zzlb.HZMC in('党支部') then 3 when zzlb.HZMC in('党小组') then 4 else 5 end) as ZZLB from ZZ_ZZQKXX z left join ZZ_ZZQKXXFB fb on z.DZZDM=fb.DZZDM left join ZZZD_ZZLBDMNEW zzlb on fb.ZZLB=zzlb.BM where 1=1 and z.DZZDM like concat('',#{gddwdm},'%')
and z.DZZDM like concat('%',#{dzzdm},'%')
and z.DZZDM =#{ssdzzdm}
) tt1 group by ZZLB ) t2 on t1.ZZLB=t2.ZZLB order by t1.ZZLB

select dickey as LEADERTYPE,t.USERCODE,ifnull(t.count,0) as COUNT,ifnull(t.quarter,0) QUARTER , d.DICVALUE as LEADERTYPENAME from (select * from CF_DICTIONARY where DICTYPEKEY='leaderType') d
                                                                                             left join (select us.XMPY,u.USERCODE,u.LEADERTYPE,count(*) as count,QUARTER ( LEADERTIME ) quarter from US_USERLEADER U
                                                                                             inner join VM_RYJBXX us on U.USERCODE = us.RYBM
                                                                                                        where 1=1
                                                                                                        and u.USERCODE=#{userCode}
                                                                                                        and date_format(LEADERTIME,'%Y')=#{year}
                                                                                                        group by us.XMPY,u.USERCODE,u.LEADERTYPE,QUARTER(LEADERTIME)
  ) t on d.DICKEY=t.LEADERTYPE
  order by DICKEY,t.XMPY

select ifnull(sum(case when s.CGJQTYPE=1 and s.GQTYPE=1 then 1 else 0 end),0) as POSTCOUNT,-- 党员先锋岗 ifnull(sum(case when s.CGJQTYPE=2 and s.GQTYPE=1 then 1 else 0 end),0) as AREACOUNT,-- 红旗责任区 ifnull(sum(case when s.CGJQTYPE=1 then 1 else 0 end),0) as POSTTOTAL,-- 责任岗 ifnull(sum(case when s.CGJQTYPE=2 then 1 else 0 end),0) as AREATOTAL -- 责任区 from CGJQ_POSTAREA_SCORE s where 1=1 and s.OPERATESTATE <> 'D'
and s.PARTYCODE like concat('',#{dzzdm},'%')
and s.PARTYCODE = #{ssdzzdm}
and s.YEAR =#{year}

select #{year} as YEAR,t1.QUARTER,ifnull(t2.POSTCOUNT,0) as POSTCOUNT,ifnull(t2.AREACOUNT,0) as AREACOUNT from (select dic.DICKEY as QUARTER from cf_dictionary dic where dic.DICTYPEKEY='monthType' and dic.DICKEY <= 4) t1 left join ( select s.YEAR,s.QUARTER, sum(case when s.CGJQTYPE=1 then 1 else 0 end) as postcount, sum(case when s.CGJQTYPE=2 then 1 else 0 end) as areacount from CGJQ_POSTAREA_SCORE s where s.GQTYPE=1 and s.OPERATESTATE <> 'D' and s.YEAR =#{year}
and s.PARTYCODE like concat('',#{dzzdm},'%')
and s.PARTYCODE = #{ssdzzdm}
group by s.YEAR,s.QUARTER ) t2 on t1.QUARTER=t2.QUARTER order by t1.QUARTER

select bz.RYBM,bz.XM,ifnull(stud.count,0) COUNT,ifnull(stud.speaknumber,0) SPEAKNUMBER, ifnull(stud.absentCount,0) ABSENTCOUNT,(case when stud.count>0 then round(ifnull(stud.absentCount,0)/stud.count,4) else 0 end) as RATE, uszw.DNZW as DNZW from ZZ_BZCYXX bz inner join VM_RYJBXX u on bz.RYBM=u.RYBM left join vw_partyduty uszw on u.rybm=uszw.rybm -- 党内职务名称 inner join ZZ_ZZQKXXFB fb on bz.DZZDM=fb.DZZDM and bz.JC=fb.LDJTJC left join( select u.LEADER_USER_ID,count(*) as count,sum(u.SPEAKNUMBER) as speaknumber, sum(case when (u.absent is null or u.absent=0) then 1 else 0 end) as absentCount from ZZ_ZXZXX_FA F inner join ZZ_ZXZXX_CJLDBZ u on f.ID=u.CASE_ID where 1=1 and f.DELETED = 0 and u.DELETED = 0
and date_format(F.STUDY_START_TIME,'%Y') = #{year}
group by u.LEADER_USER_ID ) stud on bz.RYBM=stud.LEADER_USER_ID where 1=1
and fb.DZZDM like concat('',#{dzzdm},'%')
and fb.DZZDM = #{ssdzzdm}
order by u.XMPY,u.RYJBXXBS

select dic.DICKEY as TYPE,dic.DICVALUE as NAME,count(1) as COUNT from DJ_DJKPXX kp inner join ZZ_ZZQKXX zz on kp.DZZDM = zz.DZZDM inner join CF_DICTIONARY dic on kp.JUDGELEVEL = dic.DICKEY and dic.DICTYPEKEY='judgeLevel' where kp.JUDGELEVEL in (1,2,3,4) and kp.OPERATESTATE <> 'D'
and kp.YEAR = #{year}
group by dic.DICKEY,dic.DICVALUE order by DICKEY
